const promptCycle=promptActivities.length*promptQuestions.length;
const promptDayCount=promptCycle/5;
const localPromptDay=()=>{const d=new Date();return Math.floor(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())/86400000)};
const promptEpoch=Math.floor(Date.UTC(2026,10,26)/86400000);
const mod=(a,b)=>((a%b)+b)%b;
function dailySet(day){const offset=mod(day-promptEpoch,promptDayCount)*5;return Array.from({length:5},(_,slot)=>{const id=mod((offset+slot)*73+137,promptCycle);const topic=promptActivities[id%promptActivities.length],question=promptQuestions[Math.floor(id/promptActivities.length)].replaceAll('{a}',topic).replace(/\bde ([aeiouéèêëîïôùûüœ])/gi,'d’$1');return {id,question}})}
let promptKey='',promptState={index:0,done:[]};
const promptStorageKey=()=> 'dailyPromptState:'+(sessionUser?.id||'guest');
function promptText(en,fr){return language==='fr'?fr:en}
function setPromptLabel(id,en,fr){const b=$(id),label=promptText(en,fr);b.title=label;b.setAttribute('aria-label',label)}
function refreshPrompt(){const day=localPromptDay(),storage=promptStorageKey(),key=storage+':'+day;const set=dailySet(day);if(key!==promptKey){promptKey=key;const stored=get(storage,null);promptState=stored?.day===day?{index:Math.min(4,Math.max(0,Number(stored.index)||0)),done:Array.isArray(stored.done)?stored.done.filter(x=>set.some(p=>p.id===x)):[]}:{index:0,done:[]};}const p=set[promptState.index],done=promptState.done.includes(p.id);$('dailyPrompt').textContent=p.question;$('promptPosition').textContent=(promptState.index+1)+' / 5';$('promptPrev').disabled=promptState.index===0;$('promptNext').disabled=promptState.index===4;$('promptCheck').setAttribute('aria-pressed',String(done));setPromptLabel('promptPrev','Previous prompt','Question précédente');setPromptLabel('promptNext','Next prompt','Question suivante');setPromptLabel('promptCheck',done?'Mark prompt as not completed':'Mark prompt as completed',done?'Marquer comme non terminée':'Marquer comme terminée');$('promptStatus').textContent=done?promptText('Done','Terminée'):'';}
function savePromptState(){put(promptStorageKey(),{day:localPromptDay(),index:promptState.index,done:promptState.done})}
function stepPrompt(delta){refreshPrompt();promptState.index=Math.min(4,Math.max(0,promptState.index+delta));savePromptState();refreshPrompt()}
$('promptPrev').addEventListener('click',()=>stepPrompt(-1));$('promptNext').addEventListener('click',()=>stepPrompt(1));$('promptCheck').addEventListener('click',()=>{refreshPrompt();const id=dailySet(localPromptDay())[promptState.index].id;promptState.done=promptState.done.includes(id)?promptState.done.filter(x=>x!==id):[...promptState.done,id];savePromptState();refreshPrompt()});document.addEventListener('visibilitychange',refreshPrompt);setInterval(()=>{if(!document.hidden&&promptKey!==promptStorageKey()+':'+localPromptDay())refreshPrompt()},30000);

refreshPrompt();$('title').value=draft.title;$('body').value=draft.body;$('visibility').value=draft.visibility;function updateDraft(){if(!editing)put('draft',{title:$('title').value,body:$('body').value,visibility:$('visibility').value});$('words').textContent=words($('body').value)+' mots';$('save').disabled=!$('body').value.trim();$('save').textContent=$('visibility').value==='public'?T('Publish'):T('Save journal')}['title','body','visibility'].forEach(k=>$(k).addEventListener('input',updateDraft));updateDraft();
function go(tab,notice=''){if((tab==='journal'||tab==='settings')&&!profile)tab='profile';active=tab;const u=new URL(location.origin);if(tab==='publicProfile'){const id=viewedAuthor==='self'?sessionUser?.id:viewedAuthor;if(id)u.searchParams.set('profile',id)}else if(tab!=='write')u.searchParams.set('view',tab);history.replaceState(null,'',u.pathname+u.search);document.querySelectorAll('.view').forEach(v=>{v.hidden=v.id!==tab;v.classList.remove('reveal')});const v=$(tab);void v.offsetWidth;v.classList.add('reveal');document.querySelectorAll('nav [data-go]').forEach(b=>{if(b.dataset.go===tab||((tab==='settings'||(tab==='publicProfile'&&viewedAuthor==='self'))&&b.dataset.go==='profile'))b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});showNotice(notice);render();window.scrollTo({top:0,behavior:'instant'})}document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$('filter').onchange=render;
async function save(){const body=$('body').value.trim();if(!body)return;if(!sessionUser){signup=true;go('profile',T('Sign in to save your journal.'));return}if(!profile){go('profile',T('Choose a display name first.'));return}const id=sessionUser.id,values={title:$('title').value.trim(),body,visibility:$('visibility').value};$('save').disabled=true;try{check(editing?await supabase.from('journal_entries').update(values).eq('id',editing).eq('user_id',id):await supabase.from('journal_entries').insert({...values,user_id:id}));if(sessionUser?.id!==id)return;editing=null;$('title').value='';$('body').value='';$('visibility').value=profile.defaultPrivacy||'private';updateDraft();await refreshLive();go('journal',T('Journal saved. À demain !'))}catch(e){showNotice(e.message);updateDraft()}}$('save').onclick=save;
let followed=[],feedMode='all',viewedAuthor=null,bookmarks=[],visits=[],notifications=[];let lastVisitKey='';async function recordVisit(){if(!profile||!sessionUser)return;const now=new Date(),day=localISO(now),key=sessionUser.id+':'+day;if(lastVisitKey===key)return;lastVisitKey=key;const r=await supabase.from('journal_visits').insert({user_id:sessionUser.id,day});if(r.error&&r.error.code!=='23505'){lastVisitKey='';return}if(!visits.includes(now.toDateString()))visits.push(now.toDateString())}
async function refreshLive(){const epoch=++liveEpoch,id=sessionUser?.id||null;try{const d=await loadData(sessionUser);if(epoch!==liveEpoch||id!==(sessionUser?.id||null))return;directory={...directory,...d.directory};({profile,own,samples,likes,followed,bookmarks,visits,notifications}=d);commentCounts=d.counts;await recordVisit();if(epoch===liveEpoch)render();}catch(e){if(epoch===liveEpoch)showNotice(T('Community is unavailable right now. Your draft stays on this device.')+' '+e.message)}}
async function persistProfile(p){await saveProfile(p);await refreshLive()}
async function syncSession(u){const old=sessionUser?.id||null,newId=u?.id||null;if(loadedSession&&old===newId)return;loadedSession=true;liveEpoch++;sessionUser=u||null;profile=null;own=[];samples=[];directory={};comments={};likes={};followed=[];bookmarks=[];visits=[];notifications=[];publicVisits={};openComments.clear();editing=null;feedMode='all';lastVisitKey='';if(u&&!old){try{const g=localStorage.getItem('arpree-draft-guest'),k=storageKey('draft');if(g&&!localStorage.getItem(k)){localStorage.setItem(k,g);localStorage.removeItem('arpree-draft-guest')}}catch{}}draft=get('draft',{title:'',body:'',visibility:'private'});$('title').value=draft.title||'';$('body').value=draft.body||'';$('visibility').value=draft.visibility||'private';updateDraft();$('editorHelp').textContent=T(u?'Draft on this device':'Sign in to save your journal online. You can start writing now.');render();await refreshLive()}
async function signOut(){const r=await supabase.auth.signOut();if(r.error){showNotice(r.error.message);return}await syncSession(null);go('write',T('Signed out.'))}
async function loadAuthor(id){if(id==='self'||id===sessionUser?.id){viewedAuthor='self';go('publicProfile');return}if(!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(id))return;try{const d=await loadPublic(id);directory[id]=d.author;publicVisits[id]=d.visits;samples=samples.filter(e=>e.userId!==id);for(const row of d.rows||[]){samples.push(entry(row,directory));likes[row.id]=row.journal_likes?.some(l=>l.user_id===sessionUser?.id);commentCounts[row.id]=row.journal_comments?.length||0}viewedAuthor=id;go('publicProfile')}catch(e){showNotice(e.message)}}
async function toggleFollow(a){if(!profile){go('profile',T('Sign in to follow writers.'));return}try{check(followed.includes(a.id)?await supabase.from('journal_follows').delete().eq('user_id',sessionUser.id).eq('target_id',a.id):await supabase.from('journal_follows').insert({user_id:sessionUser.id,target_id:a.id}));await refreshLive()}catch(e){showNotice(e.message)}}
async function toggleLike(e){if(!profile){go('profile',T('Sign in to appreciate journals.'));return}try{check(likes[e.id]?await supabase.from('journal_likes').delete().eq('entry_id',e.id).eq('user_id',sessionUser.id):await supabase.from('journal_likes').insert({entry_id:e.id,user_id:sessionUser.id}));await refreshLive()}catch(x){showNotice(x.message)}}
async function toggleBookmark(e){if(!profile){go('profile',T('Sign in to save public journals.'));return}try{check(bookmarks.includes(e.id)?await supabase.from('journal_bookmarks').delete().eq('entry_id',e.id).eq('user_id',sessionUser.id):await supabase.from('journal_bookmarks').insert({entry_id:e.id,user_id:sessionUser.id}));await refreshLive()}catch(x){showNotice(x.message)}}
async function shareActivity(e){if(!profile||ownEntry(e))return;const r=await supabase.from('journal_shares').insert({entry_id:e.id,user_id:sessionUser.id});if(r.error&&r.error.code!=='23505')showNotice(r.error.message)}
async function readComments(e){try{const rows=check(await supabase.from('journal_comments').select('body,journal_profiles(display_name)').eq('entry_id',e.id).order('created_at').limit(100));comments[e.id]=(rows||[]).map(x=>({name:x.journal_profiles?.display_name||'Membre',body:x.body}));render()}catch(x){showNotice(x.message)}}
async function addResponse(e,body){if(!profile){go('profile',T('Sign in to respond.'));return}if(!body.trim())return;try{check(await supabase.from('journal_comments').insert({entry_id:e.id,user_id:sessionUser.id,body:body.trim()}));await readComments(e);await refreshLive()}catch(x){showNotice(x.message)}}
async function reportEntry(e){if(!profile){go('profile',T('Sign in to report a journal.'));return}const reason=prompt(T('Why are you reporting this entry?'));if(!reason?.trim())return;try{check(await supabase.from('journal_reports').insert({entry_id:e.id,user_id:sessionUser.id,reason:reason.trim()}));showNotice(T('Report received. Thank you.'))}catch(x){showNotice(x.message)}}
async function deleteEntry(e){if(!confirm(T('Delete this journal entry permanently?')))return;try{check(await supabase.from('journal_entries').delete().eq('id',e.id).eq('user_id',sessionUser.id));await refreshLive()}catch(x){showNotice(x.message)}}
async function initialLoad(){const qs=new URLSearchParams(location.search),initialProfile=qs.get('profile'),view=qs.get('view');const r=await supabase.auth.getSession();if(r.error)showNotice(r.error.message);await syncSession(r.data?.session?.user||null);if(initialProfile)await loadAuthor(initialProfile);else if(view==='register'||view==='login'){signup=view==='register';go('profile')}else if(['write','explore','journal','profile','settings'].includes(view))go(view);supabase.auth.onAuthStateChange((event,s)=>{if(event!=='INITIAL_SESSION')setTimeout(()=>syncSession(s?.user||null),0)});setInterval(async()=>{if(!document.hidden&&sessionUser){await refreshNotifications();recordVisit()}},30000)}
async function refreshNotifications(){const id=sessionUser?.id;if(!id)return;try{const data=await notificationData(own);if(sessionUser?.id!==id)return;notifications=data;updateBell();if($('notificationDialog').open)renderNotifications()}catch{}}
Object.assign(dictionary,{"Google Pay is not available yet.":"Google Pay n’est pas encore disponible.","Sign in to save your journal.":"Connectez-vous pour enregistrer votre journal.","Choose a display name first.":"Choisissez d’abord un nom affiché.","Journal saved. À demain !":"Journal enregistré. À demain !","Signed out.":"Déconnecté.","Sign in to appreciate journals.":"Connectez-vous pour apprécier les journaux.","Sign in to respond.":"Connectez-vous pour répondre.","Sign in to report a journal.":"Connectez-vous pour signaler un journal.","Why are you reporting this entry?":"Pourquoi signalez-vous cette entrée ?","Report received. Thank you.":"Signalement reçu. Merci.","Delete this journal entry permanently?":"Supprimer définitivement cette entrée ?","Check your email to confirm your account.":"Vérifiez votre e-mail pour confirmer votre compte.","Settings saved.":"Paramètres enregistrés.","Public profile link":"Lien du profil public","Copy link":"Copier le lien","Share this link anywhere.":"Partagez ce lien où vous voulez.","Choose a display name to begin.":"Choisissez un nom affiché pour commencer.","Community is unavailable right now. Your draft stays on this device.":"La communauté est indisponible. Votre brouillon reste sur cet appareil."});
function ownEntry(e){return !!sessionUser&&e.userId===sessionUser.id}
function authorFor(e){return ownEntry(e)?profile?{...profile,id:'self'}:null:directory[e.userId]||null}
Object.assign(dictionary,{"Account Private": "Compte privé", "Make my account private": "Rendre mon compte privé", "Private accounts show only your name, bio and French level. Journals, calendar, following and sharing are hidden.": "Les comptes privés affichent uniquement votre nom, votre bio et votre niveau de français. Les journaux, le calendrier, le suivi et le partage sont masqués.", "Show my public journals": "Afficher mes journaux publics", "Show my writing calendar": "Afficher mon calendrier d’écriture", "Show when I joined Arpree": "Afficher ma date d’inscription à Arpree", "Only explicitly public journals can appear. Turning off journals hides them from Explore, shared profiles and sharing. Their original visibility settings are retained. The calendar can reveal sign-in days and public writing days.": "Seuls les journaux explicitement publics peuvent apparaître. Désactiver les journaux les masque dans Explorer, les profils partagés et le partage. Leurs paramètres de visibilité d’origine sont conservés. Le calendrier peut révéler les jours de connexion et d’écriture publique.", "Public profile enabled": "Profil public activé", "This account is private.": "Ce compte est privé.", "This profile is not available.": "Ce profil est indisponible.", "Writing calendar": "Calendrier d’écriture", "Public — hidden by account settings": "Public — masqué par les paramètres du compte"});
function publicEnabled(a){return Boolean(a&&!a.privateAccount&&a.publicProfile===true)}
function journalsVisible(a){return publicEnabled(a)&&a.showJournals!==false}
function publicEntry(e){return e.visibility==='public'&&!e.hidden&&journalsVisible(authorFor(e))}
function publicOwn(){return own.filter(publicEntry)}

function showAuthor(a){loadAuthor(a.id)}
function profileShare(a){if(a.id==='self')a=profile?{...profile,id:'self'}:null;if(!publicEnabled(a))return;const d=$('profileShareDialog'),root=$('profileShareContent');root.replaceChildren();const head=el('div',undefined,'row spread'),h=el('h2',T('Share profile'));h.id='profileShareHeading';head.append(h,control('close',T('Close'),()=>d.close()));root.append(head);const id=a.id==='self'?sessionUser.id:a.id,url=new URL(location.origin);url.pathname='/profile/'+encodeURIComponent(id);const status=el('p','','muted'),box=el('div',undefined,'profile-link-field'),label=el('label',T('Public profile link')),input=el('input',undefined,'field');input.readOnly=true;input.value=url.href;label.append(input);const copy=btn(T('Copy link'),async()=>{try{await navigator.clipboard.writeText(input.value);status.textContent=T('Link copied.')}catch{input.focus();input.select();status.textContent=T('Copy the selected link manually.')}},'primary');box.append(label,copy);root.append(box,el('p',T('Share this link anywhere.'),'muted'),status);d.showModal()}
function openProfileHash(){const id=new URLSearchParams(location.search).get('profile');if(id)loadAuthor(id)}
function publicCalendar(root,a){const cal=el('section',undefined,'section public-calendar');cal.append(el('h2',T('Writing calendar')));const header=el('div',undefined,'calendar-header');const prev=btn('‹',()=>{publicCalendarDate=new Date(publicCalendarDate.getFullYear(),publicCalendarDate.getMonth()-1,1);renderPublic()}),next=btn('›',()=>{publicCalendarDate=new Date(publicCalendarDate.getFullYear(),publicCalendarDate.getMonth()+1,1);renderPublic()});prev.setAttribute('aria-label',T('Previous month'));next.setAttribute('aria-label',T('Next month'));header.append(prev,el('strong',publicCalendarDate.toLocaleDateString(language,{month:'long',year:'numeric'})),next);cal.append(header);const grid=el('div',undefined,'calendar');for(const d of (language==='fr'?['L','M','M','J','V','S','D']:['M','T','W','T','F','S','S']))grid.append(el('span',d,'calendar-label'));const y=publicCalendarDate.getFullYear(),m=publicCalendarDate.getMonth(),offset=(new Date(y,m,1).getDay()+6)%7,days=new Date(y,m+1,0).getDate(),written=new Set((a.id==='self'?publicOwn():samples.filter(e=>e.userId===a.id&&publicEntry(e))).map(e=>new Date(e.created).toDateString()));for(let i=0;i<offset;i++)grid.append(el('span'));for(let i=1;i<=days;i++){const dt=new Date(y,m,i).toDateString(),has=written.has(dt),visited=has||(a.id==='self'?visits:publicVisits[a.id]||[]).includes(dt),cell=el('span',String(i),'calendar-day'+(visited?' visited':'')+(has?' written':''));cell.title=dt+(has?T(' — journal written'):visited?T(' — signed in'):'');cell.setAttribute('aria-label',cell.title);grid.append(cell)}cal.append(grid);root.append(cal)}
let publicCalendarDate=new Date();
function renderPublic(){const root=$('publicProfileContent');root.className='public-profile';root.replaceChildren();const a=viewedAuthor==='self'?(profile?{...profile,id:'self'}:null):directory[viewedAuthor];const isSelf=viewedAuthor==='self';root.append(btn(T(isSelf?'← Back to profile':'Back to Explore'),()=>go(isSelf?'profile':'explore')));if(!a){root.append(el('p',T('This profile is not available.'),'muted'));return}const enabled=publicEnabled(a),top=el('div',undefined,'profile-top'),info=el('div');info.append(el('div',T(enabled?'Public profile':'Account Private'),'eyebrow'));const identity=el('div',undefined,'identity'),idText=el('div');idText.append(el('h1',a.name+'.'));if(a.level&&(!enabled||a.showLevel!==false))idText.append(el('div',a.level+' · '+T('Learning French'),'muted'));if(enabled&&a.joined&&a.showJoined===true)idText.append(el('small',T('Member since ')+new Date(a.joined).toLocaleDateString(language,{month:'long',year:'numeric'})));if(enabled)identity.append(avatarNode(a));identity.append(idText);info.append(identity);if(a.bio&&(!enabled||a.showBio!==false))info.append(el('p',a.bio,'muted profile-bio'));top.append(info);root.append(top);if(!enabled){root.append(el('p',T('This account is private.'),'muted'));if(isSelf)root.append(btn(T('Manage public profile settings'),()=>go('settings'),'primary'));return}const actions=el('div',undefined,'profile-actions');if(isSelf)actions.append(el('small',T('Public profile preview — this is what other people can see.')),btn(T('Settings'),()=>go('settings')));else{const b=btn(T(followed.includes(a.id)&&profile?'Unfollow':'Follow'),()=>toggleFollow(a),'primary');b.setAttribute('aria-pressed',String(Boolean(profile&&followed.includes(a.id))));actions.append(b)}actions.append(actionBtn('share',T('Share profile'),()=>profileShare(a)));info.append(actions);if(a.showCalendar===true)publicCalendar(root,a);if(journalsVisible(a)){const sec=el('section',undefined,'section');sec.append(el('h2',T('Public journals')),el('p',T('Only public journals appear here.'),'muted'));const data=isSelf?publicOwn():samples.filter(e=>e.userId===a.id&&publicEntry(e));if(!data.length)sec.append(el('p',T('No public journals here yet.'),'muted'));data.forEach(e=>sec.append(entryCard(e,false,isSelf)));root.append(sec)}}
function renderExplore(all){const sw=$('feedSwitch');sw.replaceChildren();for(const [id,label] of [['all','All journals'],['following','Following'],['saved','Saved journals']]){const b=btn(T(label),()=>{if(id!=='all'&&!profile){go('profile',T(id==='saved'?'Sign in to save public journals.':'Sign in to follow writers.'));return}feedMode=id;render()});b.setAttribute('aria-pressed',String(feedMode===id));sw.append(b)}let data=all.filter(e=>!$('filter').value||(authorFor(e)?.showLevel!==false&&e.level===$('filter').value));if(feedMode==='following'){data=data.filter(e=>profile&&followed.includes(authorFor(e)?.id));if(!data.length){$('exploreFeed').replaceChildren(el('p',T('Follow a writer to see their public journals here.'),'muted'));return}}if(feedMode==='saved'){data=data.filter(e=>profile&&bookmarks.includes(e.id));if(!data.length){$('exploreFeed').replaceChildren(el('p',T('Save journals you enjoy to find them here.'),'muted'));return}}feed('exploreFeed',data)}

