function iconNode(name){const v=document.createElementNS('http://www.w3.org/2000/svg','svg');v.setAttribute('viewBox','0 0 24 24');v.setAttribute('aria-hidden','true');v.setAttribute('class',name);v.innerHTML=actionPaths[name];return v}
function actionBtn(name,label,fn,count,pressed){const b=btn('',fn,'action-icon');b.append(iconNode(name));b.setAttribute('aria-label',label+(count===undefined?'':' · '+count));b.dataset.tooltip=label;if(count!==undefined)b.append(el('span',String(count),'action-count'));if(pressed!==undefined)b.setAttribute('aria-pressed',String(pressed));return b}
Object.assign(dictionary,{"Choose a platform":"Choisissez une plateforme","The image will download and the selected platform will open. Attach the image there to share your journal.":"L’image sera téléchargée et la plateforme sélectionnée s’ouvrira. Joignez l’image pour partager votre journal.","Image download started. Attach it on the selected platform.":"Téléchargement de l’image lancé. Joignez-la sur la plateforme sélectionnée.","This is a local preview, not a live journal link. Nothing is posted automatically.":"Ceci est un aperçu local, pas un lien vers un journal en ligne. Rien n’est publié automatiquement."});

function control(name,label,fn,pressed){const b=btn('',fn,'icon-control');b.append(iconNode(name));b.dataset.tooltip=label;b.setAttribute('aria-label',label);b.title=label;if(pressed!==undefined)b.setAttribute('aria-pressed',String(pressed));return b}

function updateBell(){const b=$('notificationButton');b.hidden=!profile;b.replaceChildren(iconNode('bell'));b.dataset.tooltip=T('Notifications');b.setAttribute('aria-label',T('Notifications'));const n=notifications.filter(x=>!x.read&&own.some(e=>e.id===x.entry&&publicEntry(e))).length;if(n){b.append(el('span',String(n),'unread-dot'));b.setAttribute('aria-label',T('Notifications')+' · '+n)}}
function renderNotifications(){const d=$('notificationDialog'),r=$('notificationContent');r.replaceChildren();const h=el('h2',T('Notifications'));h.id='notificationHeading';const head=el('div',undefined,'row spread');head.append(h,control('close',T('Close'),()=>d.close()));r.append(head);const visible=notifications.filter(x=>own.some(e=>e.id===x.entry&&publicEntry(e)));if(visible.length){r.append(control('check',T('Mark all as read'),async()=>{try{check(await supabase.from('journal_notifications').update({read:true}).eq('user_id',sessionUser.id).eq('read',false));await refreshNotifications()}catch(e){showNotice(e.message)}}));for(const n of visible){const row=el('div',undefined,'notification-row'+(n.read?'':' unread')),copy=el('div');copy.append(el('p',n.actor+' '+T({heart:'appreciated your post',bookmark:'saved your post',share:'shared your post'}[n.type])+'.'),el('small',n.title+' · '+new Date(n.at).toLocaleDateString(language)));row.append(iconNode(n.type),copy);if(!n.read)row.append(el('span',undefined,'new-dot'));r.append(row)}}else r.append(el('p',T('No notifications yet.'),'muted'))}
$('notificationButton').onclick=()=>{renderNotifications();$('notificationDialog').showModal();refreshNotifications()};
