function updateLocalClock(now=new Date()){
 const locale=language==='fr'?'fr-FR':'en-GB';
 const day=new Intl.DateTimeFormat(locale,{weekday:'long'}).format(now);
 const h=now.getHours();
 const greeting=language==='fr'?(h<18?'Bonjour':'Bonsoir'):(h<5?'Good evening':h<12?'Good morning':h<18?'Good afternoon':'Good evening');
 const dateLabel=new Intl.DateTimeFormat(locale,{weekday:'short',day:'numeric',month:'short',year:'numeric'}).format(now);
 const timeLabel=new Intl.DateTimeFormat(locale,{hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(now);
 $('localDate').textContent=dateLabel;$('localDate').dateTime=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0')+'-'+String(now.getDate()).padStart(2,'0');
 $('localTime').textContent=timeLabel;$('localTime').dateTime=String(h).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0');
 $('siteClock').setAttribute('aria-label',language==='fr'?'Date et heure locales':'Local date and time');
 $('heroEyebrow').textContent=profile&&own.length?greeting:T('A little French, every day');
}
